// Forwards the calibration user's navigation through the manual calibration
// screens ("Broadcasts forward and back messages generated by the
// 'calibration user'."; author Buzz Burrowes;
// rb_meta/ManualCalibrationFlowCom.o, 0xDB9380-0xDBA25F with the static
// initializer at 0xDBA1A0). Its class symbol is "ManualCalibrationFlow".
// The component takes the root's input first and exports
// "calibration_flow" with the direction for the calibration user's cancel,
// confirm (unless the screen waits for its confirm button) and shell option
// buttons. The vtable at 0x1981AD8 has 42 slots. The object is 40 bytes.
class ManualCalibrationFlowCom : public Component {
public:
    // The "direction" of a "calibration_flow" event; the names follow the
    // allowed values' texts. Name not in the reference map.
    enum FlowDirection {
        kFlowBack = -1,
        kFlowForward = 1,
        kFlowShellOption = 2,
    };

    ManualCalibrationFlowCom();  // 0xDB9380
    // The imprint's copy starts afresh. Inlined into _Imprint (0xDBA030).
    // Not in the reference map.
    ManualCalibrationFlowCom(const ManualCalibrationFlowCom& other)
        : Component(other), mFlowUser(nullptr), mFlowPadNum(-1), mAwaitingConfirmButton(false) {}
    // Slots 0-1: 0xDB9920, 0xDB9F90.
    ~ManualCalibrationFlowCom() override;

    // Slot 2: "ui_button_down" goes to OnMsg; other messages are unhandled.
    DataNode Handle(DataArray* msg, bool warn) override;  // 0xDB9E60
    Symbol GetId() const override;          // slot 4: 0xDB9FB0
    Symbol GetClassName() const override;   // slot 5: 0xDB9FC0
    int CurrentRev() const override;        // slot 7: 0xDB9FD0
    bool IsA(Symbol type) const override;   // slot 8: 0xDB9FF0
    Component* AsComponent() override;      // slot 9: 0xDBA020
    // Slot 10. The map's _Imprint(char*, Component*&, bool).
    char* _Imprint(char* buffer, Component** imprint) override;  // 0xDBA030
    // Slot 20: takes the input back from the root's RBUIInputCom. The map's
    // _PreDestroy(ObjPtr const&, DestroyType).
    void _PreDestroy(DestroyType type) override;  // 0xDB9A00
    PropRegistry& _GetPropRegistry() override;  // slot 22: 0xDBA160
    ComMetaData& _GetMetaData() override;       // slot 23: 0xDBA170
    // Slot 31: follows the meta state's calibration user and gives the
    // component the root's input first; the input component is not checked
    // for null. The map's _Enter(ObjPtr const&).
    void _Enter() override;  // 0xDB9930
    // Slot 33: empty. The map's _Poll(ObjPtr const&).
    void _Poll() override;  // 0xDB99F0
    // Slot 41: exports the calibration user's navigation; other pads'
    // buttons are unhandled.
    virtual DataNode OnMsg(const UIButtonDownMsg& msg);  // 0xDB9A60

    // Follows the user's buttons; the pad is 0 without a user.
    void SetFlowUser(const User* user);  // 0xDB99C0

    // Registers the class (InitComponentClass). Inline in the map; this
    // build emits it with the other rb_meta classes' at 0xB64FA0.
    static void Init();
    // The class factory, emitted at 0xBA0D60; the placement factory beside
    // it (0xBA0D90) is InitComponentClass's.
    static Component* _Create();
    static void _Init(PropRegistry& registry, ComMetaData& metadata);  // 0xDB93C0

    // "ManualCalibrationFlow".
    static Symbol sId;  // 0x1B267F0
    // Also "ManualCalibrationFlow". Name not in the reference map.
    static Symbol sClassName;           // 0x1B267F8
    static PropRegistry sPropRegistry;  // 0x1B26800
    static ComMetaData sMetaData;       // 0x1B268A0

    // Field names are not in the reference map.
    const User* mFlowUser;
    int mFlowPadNum;
    // "awaitin_confirm_button" (sic), read and set through accessors: the
    // screen handles the confirm button itself.
    bool mAwaitingConfirmButton;
};

static_assert(offsetof(ManualCalibrationFlowCom, mFlowUser) == 24);
static_assert(offsetof(ManualCalibrationFlowCom, mFlowPadNum) == 32);
static_assert(offsetof(ManualCalibrationFlowCom, mAwaitingConfirmButton) == 36);
static_assert(sizeof(ManualCalibrationFlowCom) == 40);
